-- M11 step 5: preserve identities across natural-key collisions and read-only run history.
CREATE TABLE sync_aliases (
 workspace_id TEXT NOT NULL, user_id TEXT NOT NULL, table_name TEXT NOT NULL,
 original_id TEXT NOT NULL, canonical_id TEXT NOT NULL,
 created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
 PRIMARY KEY (workspace_id,table_name,original_id)
);
CREATE INDEX sync_alias_target ON sync_aliases(workspace_id,table_name,canonical_id);
ALTER TABLE sync_inbox ADD COLUMN blocked TEXT;
ALTER TABLE runs ADD COLUMN sync_owner TEXT;
DROP INDEX artifact_versions_order;
CREATE INDEX artifact_versions_order ON artifact_versions(artifact_id,version,id);

-- Preserve scheduled cost attribution without replicating schedules or execution ownership.
DROP TRIGGER sync_threads_insert;
CREATE TRIGGER sync_threads_insert AFTER INSERT ON threads
 WHEN EXISTS (SELECT 1 FROM sync_state WHERE workspace_id=NEW.workspace_id AND enabled=1 AND applying=0) AND (((NEW.deleted_at IS NULL OR NEW.purged_at IS NOT NULL)) AND ((NEW.incognito=0 AND ((NEW.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.workspace_id=NEW.workspace_id AND p.privacy_mode!='local_only')))) OR EXISTS (SELECT 1 FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='threads' AND record_key=NEW.id)))
 BEGIN
 UPDATE sync_state SET seq=seq+1,clock=clock+1 WHERE workspace_id=NEW.workspace_id;
 INSERT INTO sync_outbox (id,workspace_id,user_id,table_name,record_key,device_id,seq,clock,version,operation,payload,created_at,updated_at)
 SELECT device_id||':'||seq,NEW.workspace_id,NEW.user_id,'threads',NEW.id,device_id,seq,clock,
 json_set(COALESCE((SELECT version FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='threads' AND record_key=NEW.id),'{}'),'$."'||device_id||'"',seq),
 CASE WHEN NOT (NEW.incognito=0 AND ((NEW.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.workspace_id=NEW.workspace_id AND p.privacy_mode!='local_only')))) THEN 'withdraw' WHEN NEW.purged_at IS NOT NULL THEN 'delete' ELSE 'put' END,CASE WHEN (CASE WHEN NOT (NEW.incognito=0 AND ((NEW.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.workspace_id=NEW.workspace_id AND p.privacy_mode!='local_only')))) THEN 'withdraw' WHEN NEW.purged_at IS NOT NULL THEN 'delete' ELSE 'put' END)='put' THEN json_object('id',NEW.id,'workspace_id',NEW.workspace_id,'user_id',NEW.user_id,'title',NEW.title,'title_source',NEW.title_source,'last_message_at',NEW.last_message_at,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'deleted_at',NEW.deleted_at,'web_search',NEW.web_search,'instructions',NEW.instructions,'project_id',NEW.project_id,'memory_injection',NEW.memory_injection,'memory_checked_at',NEW.memory_checked_at,'pinned_tier',NEW.pinned_tier,'pinned_provider',NEW.pinned_provider,'pinned_model',NEW.pinned_model,'active_leaf_id',NEW.active_leaf_id,'incognito',NEW.incognito,'pinned_at',NEW.pinned_at,'archived_at',NEW.archived_at,'stay_provider',NEW.stay_provider,'kind',NEW.kind,'handoff_from_id',NEW.handoff_from_id,'run_cap_micro_usd',NEW.run_cap_micro_usd,'schedule_id',NEW.schedule_id,'purged_at',NEW.purged_at) ELSE NULL END,unixepoch()*1000,unixepoch()*1000 FROM sync_state WHERE workspace_id=NEW.workspace_id;
 INSERT INTO sync_records (workspace_id,user_id,table_name,record_key,event_id,device_id,clock,version,revision,operation,created_at,updated_at)
 SELECT workspace_id,user_id,table_name,record_key,id,device_id,clock,version,
 COALESCE((SELECT revision FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='threads' AND record_key=NEW.id),0)+1,operation,created_at,updated_at
 FROM sync_outbox WHERE id=(SELECT device_id||':'||seq FROM sync_state WHERE workspace_id=NEW.workspace_id)
 ON CONFLICT(workspace_id,table_name,record_key) DO UPDATE SET
 event_id=excluded.event_id,device_id=excluded.device_id,clock=excluded.clock,version=excluded.version,
 revision=excluded.revision,operation=excluded.operation,updated_at=excluded.updated_at;
 DELETE FROM sync_outbox WHERE workspace_id=NEW.workspace_id AND table_name='threads' AND operation='put' AND record_key IN (SELECT record_key FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='threads' AND operation!='put');
 END;
