 WHEN EXISTS (SELECT 1 FROM sync_state WHERE workspace_id=NEW.workspace_id AND enabled=1 AND applying=0) AND (((NEW.deleted_at IS NULL OR NEW.purged_at IS NOT NULL)) AND ((NEW.incognito=0 AND ((NEW.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.workspace_id=NEW.workspace_id AND p.privacy_mode!='local_only')))) OR EXISTS (SELECT 1 FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='threads' AND record_key=NEW.id))) AND ((SELECT force_capture FROM sync_state WHERE workspace_id=NEW.workspace_id)=1 OR NOT EXISTS (SELECT 1 FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='threads' AND record_key=NEW.id) OR (NEW.id IS NOT OLD.id OR NEW.workspace_id IS NOT OLD.workspace_id OR NEW.user_id IS NOT OLD.user_id OR NEW.title IS NOT OLD.title OR NEW.title_source IS NOT OLD.title_source OR NEW.last_message_at IS NOT OLD.last_message_at OR NEW.created_at IS NOT OLD.created_at OR NEW.updated_at IS NOT OLD.updated_at OR NEW.deleted_at IS NOT OLD.deleted_at OR NEW.web_search IS NOT OLD.web_search OR NEW.instructions IS NOT OLD.instructions OR NEW.project_id IS NOT OLD.project_id OR NEW.memory_injection IS NOT OLD.memory_injection OR NEW.memory_checked_at IS NOT OLD.memory_checked_at OR NEW.pinned_tier IS NOT OLD.pinned_tier OR NEW.pinned_provider IS NOT OLD.pinned_provider OR NEW.pinned_model IS NOT OLD.pinned_model OR NEW.active_leaf_id IS NOT OLD.active_leaf_id OR NEW.incognito IS NOT OLD.incognito OR NEW.pinned_at IS NOT OLD.pinned_at OR NEW.archived_at IS NOT OLD.archived_at OR NEW.stay_provider IS NOT OLD.stay_provider OR NEW.kind IS NOT OLD.kind OR NEW.handoff_from_id IS NOT OLD.handoff_from_id OR NEW.run_cap_micro_usd IS NOT OLD.run_cap_micro_usd OR NEW.purged_at IS NOT OLD.purged_at OR NEW.schedule_id IS NOT OLD.schedule_id))
