-- Legacy completed project runs may have no conversation; no thread implies no incognito scope.
DROP TRIGGER sync_runs_insert;
CREATE TRIGGER sync_runs_insert AFTER INSERT ON runs
 WHEN EXISTS (SELECT 1 FROM sync_state WHERE workspace_id=NEW.workspace_id AND enabled=1 AND applying=0) AND ((NEW.status IN ('done','stopped','error')) AND ((((NEW.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.workspace_id=NEW.workspace_id AND p.privacy_mode!='local_only'))) AND (NEW.thread_id IS NULL OR EXISTS (SELECT 1 FROM threads t WHERE t.id=NEW.thread_id AND t.workspace_id=NEW.workspace_id AND t.incognito=0 AND (t.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=t.project_id AND p.privacy_mode!='local_only'))))) OR EXISTS (SELECT 1 FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='runs' AND record_key=NEW.id)))
 BEGIN
 UPDATE sync_state SET seq=seq+1,clock=clock+1 WHERE workspace_id=NEW.workspace_id;
